#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>

#define MAX_PACKET_SIZE 4096
#define HEADER_SIZE 12
#define MAX_EXTENSIONS 8
#define EXTENSION_HEADER_SIZE 4

typedef struct {
    uint32_t magic;
    uint16_t version;
    uint16_t num_extensions;
    uint32_t payload_length;
} __attribute__((packed)) PacketHeader;

typedef struct {
    uint16_t ext_type;
    uint16_t ext_length;
} __attribute__((packed)) ExtensionHeader;

typedef struct {
    char data[MAX_PACKET_SIZE];
    size_t length;
    int authenticated;
} PacketBuffer;

static uint32_t compute_crc32(const void *data, size_t len) {
    uint32_t crc = 0xFFFFFFFF;
    const uint8_t *p = (const uint8_t *)data;
    for (size_t i = 0; i < len; i++) {
        crc ^= p[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ (0xEDB88320 & (-(crc & 1)));
        }
    }
    return ~crc;
}

static int validate_header(const PacketHeader *hdr) {
    if (hdr->magic != 0x50524F54) return -1;
    if (hdr->version < 1 || hdr->version > 3) return -1;
    if (hdr->num_extensions > MAX_EXTENSIONS) return -1;
    return 0;
}

/* Parse extensions and return total extensions size consumed */
static ssize_t parse_extensions(const char *buf, size_t buf_remaining,
                                uint16_t num_extensions,
                                char *ext_data_out, size_t ext_data_max) {
    size_t offset = 0;
    size_t total_ext_data = 0;

    for (uint16_t i = 0; i < num_extensions; i++) {
        if (offset + EXTENSION_HEADER_SIZE > buf_remaining) return -1;

        ExtensionHeader ext;
        memcpy(&ext, buf + offset, EXTENSION_HEADER_SIZE);
        offset += EXTENSION_HEADER_SIZE;

        /* Validate individual extension length */
        if (ext.ext_length > 512) return -1;

        if (offset + ext.ext_length > buf_remaining) return -1;

        /* Copy extension data if there's room */
        if (total_ext_data + ext.ext_length <= ext_data_max) {
            memcpy(ext_data_out + total_ext_data, buf + offset, ext.ext_length);
            total_ext_data += ext.ext_length;
        }

        offset += ext.ext_length;
    }

    return (ssize_t)offset;
}

/* Process the payload after extensions */
static int process_payload(const char *packet_data, size_t packet_length,
                           size_t extensions_total_size,
                           const PacketHeader *hdr,
                           char *output, size_t output_size) {
    /*
     * Calculate where payload starts and its actual size.
     * payload_length from header tells us expected payload size.
     * We verify it matches what's actually remaining in the packet.
     */
    size_t payload_offset = HEADER_SIZE + extensions_total_size;

    /* Bounds check: ensure payload_offset doesn't exceed packet */
    if (payload_offset > packet_length) return -1;

    size_t remaining = packet_length - payload_offset;

    /*
     * The payload includes a 4-byte CRC trailer.
     * Verify we have enough room for the declared payload + CRC.
     * Check for overflow in the addition first.
     */
    if (hdr->payload_length > SIZE_MAX - 4) return -1;
    size_t needed = (size_t)hdr->payload_length + 4;

    /* Check that remaining data matches expected size */
    if (remaining < needed) return -1;

    /* Validate payload fits in output buffer */
    if (hdr->payload_length > output_size) return -1;

    /* Verify CRC over the payload */
    const char *payload_start = packet_data + payload_offset;
    uint32_t computed_crc = compute_crc32(payload_start, hdr->payload_length);
    uint32_t received_crc;
    memcpy(&received_crc, payload_start + hdr->payload_length, 4);

    if (computed_crc != received_crc) return -1;

    /* Copy payload to output */
    memcpy(output, payload_start, hdr->payload_length);
    return (int)hdr->payload_length;
}

int handle_packet(const char *raw_packet, size_t raw_length) {
    char ext_buffer[2048];
    char output[2048];
    PacketHeader hdr;

    if (raw_length < HEADER_SIZE) return -1;
    if (raw_length > MAX_PACKET_SIZE) return -1;

    memcpy(&hdr, raw_packet, HEADER_SIZE);
    if (validate_header(&hdr) != 0) return -1;

    /* Parse extensions */
    size_t ext_buf_remaining = raw_length - HEADER_SIZE;
    ssize_t ext_consumed = parse_extensions(
        raw_packet + HEADER_SIZE,
        ext_buf_remaining,
        hdr.num_extensions,
        ext_buffer, sizeof(ext_buffer)
    );

    if (ext_consumed < 0) return -1;

    /* Process payload */
    int result = process_payload(
        raw_packet, raw_length,
        (size_t)ext_consumed,
        &hdr,
        output, sizeof(output)
    );

    if (result > 0) {
        printf("Processed %d bytes of payload\n", result);
    }

    return result;
}

int main(int argc, char *argv[]) {
    char packet[MAX_PACKET_SIZE];
    ssize_t n = read(STDIN_FILENO, packet, sizeof(packet));
    if (n <= 0) {
        fprintf(stderr, "Failed to read packet\n");
        return 1;
    }
    int ret = handle_packet(packet, (size_t)n);
    return (ret >= 0) ? 0 : 1;
}
